"""Front screen and views: regenerated bytes equal the committed golden files, plus the promises each view makes.

Set TRIPWRIGHT_REGENERATE=1 to rewrite the golden files after an intended format change, then review the diff.
"""
import copy
import json
import os

import pytest

from render_samples import GOLDEN, load

from tripwright.checks import departure_clock
from tripwright.render.memory import memory_problems
from tripwright.render.screens import day_view, memory_view, repo_files, repo_readme, today_view, trip_readme
from tripwright.trip import Trip

MEMORY = json.loads((GOLDEN.parent / "fixtures/memory.json").read_text(encoding="utf-8"))
FILES = {"README.md": "repo_readme.md", "trips/2030-07-seenland/README.md": "trip_readme.md",
         "trips/2030-07-seenland/views/memory.md": "memory.md", "trips/2030-07-seenland/views/today.md": "today.md",
         "trips/2030-07-seenland/views/days/2030-07-14.md": "day_2030-07-14.md",
         "trips/2030-07-seenland/views/days/2030-07-15.md": "day_2030-07-15.md",
         "trips/2030-07-seenland/views/index.md": "index.md", "trips/2030-07-seenland/views/decisions.md": "decisions.md",
         "trips/2030-07-seenland/views/packs/2030-07-15.md": "pack_2030-07-15.md"}


def generated(state, sources, *, packs=True):
    return repo_files([state], current=state["trip"]["id"], snapshot=state["snapshot"], sources=sources,
                      packs={state["trip"]["id"]: {"2030-07-15": load("pack_wide.json")}} if packs else None,
                      memory={state["trip"]["id"]: MEMORY} if packs else None)


def test_regenerated_views_equal_the_committed_golden_files(state, sources):
    files = generated(state, sources)
    assert set(files) == set(FILES)
    if os.environ.get("TRIPWRIGHT_REGENERATE"):
        GOLDEN.mkdir(exist_ok=True)
        for path, name in FILES.items():
            (GOLDEN / name).write_text(files[path], encoding="utf-8")
    for path, name in FILES.items():
        assert files[path] == (GOLDEN / name).read_text(encoding="utf-8"), path
    assert generated(copy.deepcopy(state), sources) == files


def test_every_view_starts_with_the_generated_header_naming_the_base_commit(state, sources):
    for text in generated(state, sources).values():
        first = text.splitlines()[0]
        assert first.startswith("<!-- 由 tripwright 生成，源：") and first.endswith("；不要手改 -->") and "基于提交 8b1d0e4" in first


def test_repo_front_screen_points_at_the_current_trip_within_25_lines(state):
    lines = repo_readme([state], current=state["trip"]["id"], snapshot=state["snapshot"], memory=MEMORY).splitlines()
    assert len(lines) <= 25 and lines[1] == "# 我的旅行"
    assert "现在：Seenland 两日（虚构）｜进行中，第 2 天，共 2 天｜当地时区 Europe/Vienna" in lines
    assert "agent 读法：先调 turn；没有工具就读 trips/2030-07-seenland/views/packs/2030-07-15.md" in lines
    assert "记忆：待确认 1 条｜已确认沿用 3 条｜这趟不用 2 条（trips/2030-07-seenland/views/memory.md）" in lines
    assert "- trips/2030-07-seenland/README.md：Seenland 两日（虚构）｜07-14—07-15｜进行中，第 2 天，共 2 天" in lines


def test_trip_front_screen_fits_40_lines_and_links_relative_to_its_folder(state):
    lines = trip_readme(state, memory=MEMORY).splitlines()
    assert len(lines) <= 40 and lines[1] == "# Seenland 两日（虚构）"
    assert "- views/memory.md：记忆：从以前带来的长期内容" in lines and "- views/today.md：今天" in lines


def test_memory_view_shows_words_origin_status_and_last_use(state):
    lines = memory_view(MEMORY, state=state).splitlines()
    assert lines[3] == "这趟（2030-07-seenland）：待确认 1 条｜已确认沿用 3 条｜这趟不用 2 条"
    assert ("- [I-300513-n7w] 待确认｜u1｜「早上别排太早，九点前我起不来。」｜来自 2030-05-alpen 的 E-300513-b02（u1，05-13，逐字）"
            "｜文件 profile/items/I-300513-n7w.yaml｜最近用在 2030-05-alpen 05-14") in lines
    assert [line for line in lines if line.startswith("## ")] == ["## 偏好", "## 同行人", "## 常驻规矩", "## 资料"]
    assert "（u1，05-12，转述）" in next(line for line in lines if line.startswith("- [u2]"))
    # a use recorded for the whole trip has no day; the view (and with it every commit of the trip's files) still renders
    undated = copy.deepcopy(MEMORY)
    entry = next(entry for entry in undated["entries"] if entry.get("last_used"))
    entry["last_used"]["date"] = None
    line = next(line for line in memory_view(undated, state=state).splitlines() if line.startswith(f"- [{entry['id']}]"))
    assert f"最近用在 {entry['last_used']['trip']}" in line and f"最近用在 {entry['last_used']['trip']} " not in line


def test_memory_data_without_a_source_or_nature_or_with_an_unknown_status_is_refused(state):
    broken = copy.deepcopy(MEMORY)
    broken["entries"][0]["source"]["nature"] = None
    broken["entries"][1]["status"] = "maybe"
    broken["entries"][5]["source"]["path"] = None
    problems = memory_problems(broken)
    assert len(problems) == 3 and memory_problems(MEMORY) == []
    with pytest.raises(ValueError, match="verbatim"):
        memory_view(broken, state=state)


def test_latest_departure_in_views_is_the_core_calculation(state):
    assert departure_clock("19:30", 15, 70, day="2030-07-15", zone="Europe/Vienna") == "18:05"
    assert "- 07-15 19:30 Gasthaus Lindengrund 晚饭（已订）｜u1、u2｜最晚 18:05 出发" in trip_readme(state).splitlines()
    assert "最晚 18:05 出发" in day_view(state, "2030-07-15")


def test_open_notices_come_first_and_a_trip_at_the_repo_root_has_no_folder_prefix(state):
    state = dict(state, path="", notices=[{"user_line": "上次的安排已在别处改动，需要重排。"}])
    lines = trip_readme(state).splitlines()
    assert lines[2] == "注意：上次的安排已在别处改动，需要重排。"
    assert "views/today.md" in repo_files([state], current=state["trip"]["id"], snapshot=state["snapshot"])


WARNINGS = [{"id": "person:F-300715-k2p:d2-luggage", "status": "conflict", "critical": True,
             "text": "u1 本人没有箱子，12:30 回 Pension Moorblick 取箱子这一块不成立。"},
            {"id": "item:I-300713-m0u:2030-07-15:当前安排", "status": "conflict", "critical": False,
             "text": "下午的湖边路和 u2 不走远路冲突。"}]


def test_a_plan_that_needs_replanning_says_so_in_the_day_view_and_the_front_screens(state):
    replan = dict(state, needs_replan=True, warnings=WARNINGS)
    day = day_view(replan, "2030-07-15").splitlines()
    assert day[3] == "需重排：这一版计划和后来记下的情况冲突，先重排再照它走。"
    assert day[4:6] == [f"- 冲突：{warning['text']}" for warning in WARNINGS]
    other = day_view(replan, "2030-07-14").splitlines()
    assert other[3:5] == ["需重排：这一版计划和后来记下的情况冲突，先重排再照它走。",
                          "这一天没有冲突；冲突见 trips/2030-07-seenland/README.md。"]
    assert not any(line.startswith("- 冲突：") for line in other)
    readme = trip_readme(replan).splitlines()
    assert readme[2] == "需重排：这一版计划和后来记下的情况冲突，先重排再照它走。" and len(readme) <= 40
    assert "- 冲突：下午的湖边路和 u2 不走远路冲突。" in readme
    assert "需重排：这一版计划和后来记下的情况冲突，先重排再照它走。" in today_view(replan).splitlines()
    assert "现在：Seenland 两日（虚构）｜进行中，第 2 天，共 2 天｜需重排｜当地时区 Europe/Vienna" in repo_readme(
        [replan], current=state["trip"]["id"], snapshot=state["snapshot"]).splitlines()
    # Without the flag (or with it false) nothing says replan: the golden files above hold that.
    assert "需重排" not in day_view(dict(state, needs_replan=False, warnings=WARNINGS), "2030-07-15")


def test_other_trips_come_with_their_plan_only_and_get_one_line_in_the_repository_readme(state):
    # Its bookings fall outside its dates, so today's Trip model would refuse it: an old trip's plan is read as
    # committed, and it must not stop the current trip's front screen.
    plan = dict(state["trip"], id="2030-05-alpen", title="Alpen 一日（虚构）", start="2030-05-14", end="2030-05-14",
                days=[dict(state["trip"]["days"][0], date="2030-05-14")])
    with pytest.raises(ValueError):
        Trip.model_validate(plan)
    other = dict(path="trips/2030-05-alpen", trip=plan, records={}, snapshot=state["snapshot"])
    files = repo_files([state, other], current=state["trip"]["id"], snapshot=state["snapshot"])
    assert not [path for path in files if path.startswith("trips/2030-05-alpen/")]
    lines = files["README.md"].splitlines()
    assert lines.index("- trips/2030-05-alpen/README.md：Alpen 一日（虚构）｜05-14—05-14｜已结束") < lines.index(
        "- trips/2030-07-seenland/README.md：Seenland 两日（虚构）｜07-14—07-15｜进行中，第 2 天，共 2 天")
    assert files == {**generated(state, None, packs=False), "README.md": files["README.md"]}


def test_an_opened_trip_without_a_plan_is_named_on_the_repository_front_screen(state):
    lines = repo_readme([], current="2030-08-nordkap", snapshot=state["snapshot"]).splitlines()
    assert lines[2] == "现在：2030-08-nordkap，还没有提交的计划"


def test_today_outside_the_trip_says_so_and_shows_the_next_day(state):
    before = dict(state, snapshot=dict(state["snapshot"], taken_at="2030-07-12T09:00:00+02:00"))
    lines = today_view(before).splitlines()
    assert lines[1] == "# 今天 07-12" and "今天不在行程里；下面是 07-14 · Grauwald → Altmoor。" in lines
    assert trip_readme(before).splitlines()[2].startswith("阶段：计划中")


def test_place_lines_in_views_write_the_search_out(state):
    lines = day_view(state, "2030-07-15").splitlines()
    index = lines.index("Gasthaus Lindengrund")
    assert lines[index + 1].startswith("林登格伦德餐馆 · Google 地图搜 Gasthaus Lindengrund · [Google 地图](")


def test_an_unknown_day_is_refused(state):
    with pytest.raises(ValueError, match="no day 2030-07-20"):
        day_view(state, "2030-07-20")
